#include <bits/stdc++.h>
using namespace std;

int n; // number of variables (toppings)
vector<vector<int>> adj, radj;
vector<bool> used;
vector<int> order_, comp;

void addImp(int u, int v) {
    adj[u].push_back(v);
    radj[v].push_back(u);
}
// clause (lit_a OR lit_b): a,b are variable indices (0-indexed), na/nb true means negated
void addClause(int a, bool na, int b, bool nb) {
    int A = 2*a ^ (na?1:0);   // node for literal a (na=false-> "a true" node)
    int B = 2*b ^ (nb?1:0);
    int notA = A ^ 1;
    int notB = B ^ 1;
    addImp(notA, B);
    addImp(notB, A);
}
void dfs1(int v) {
    used[v] = true;
    for (int u : adj[v]) if (!used[u]) dfs1(u);
    order_.push_back(v);
}
void dfs2(int v, int cl) {
    comp[v] = cl;
    for (int u : radj[v]) if (comp[u] == -1) dfs2(u, cl);
}

int main(){
    int m; // number of opinions/persons
    cin >> n >> m;
    int N = 2*n;
    adj.assign(N, {}); radj.assign(N, {});
    for (int i = 0; i < m; i++) {
        string t1, t2;
        cin >> t1 >> t2;
        bool na = (t1[0]=='-');
        int a = stoi(t1.substr(1)) - 1;
        bool nb = (t2[0]=='-');
        int b = stoi(t2.substr(1)) - 1;
        addClause(a, na, b, nb);
    }
    used.assign(N, false);
    for (int i = 0; i < N; i++) if (!used[i]) dfs1(i);
    comp.assign(N, -1);
    int j = 0;
    for (int i = 0; i < N; i++) {
        int v = order_[N-i-1];
        if (comp[v] == -1) dfs2(v, j++);
    }
    vector<int> val(n);
    bool ok = true;
    for (int i = 0; i < n; i++) {
        if (comp[2*i] == comp[2*i+1]) { ok = false; break; }
        val[i] = (comp[2*i] > comp[2*i+1]) ? 1 : 0; // node 2*i = "true" literal
    }
    if (!ok) { cout << "IMPOSSIBLE" << endl; return 0; }
    for (int i = 0; i < n; i++) cout << (val[i] ? '+' : '-') << (i+1<n? ' ' : '\n');
}

#include <bits/stdc++.h>
using namespace std;

int n; // number of switches
vector<vector<int>> adj, radj;
vector<bool> used;
vector<int> order_, comp;

void addImp(int u, int v) { adj[u].push_back(v); radj[v].push_back(u); }
// clause (lit_a OR lit_b), a,b 0-indexed switch ids, na/nb = negated?
void addClause(int a, bool na, int b, bool nb) {
    int A = 2*a ^ (na?1:0);
    int B = 2*b ^ (nb?1:0);
    int notA = A ^ 1, notB = B ^ 1;
    addImp(notA, B);
    addImp(notB, A);
}
void dfs1(int v){ used[v]=true; for(int u:adj[v]) if(!used[u]) dfs1(u); order_.push_back(v); }
void dfs2(int v,int cl){ comp[v]=cl; for(int u:radj[v]) if(comp[u]==-1) dfs2(u,cl); }

int main(){
    int m; // number of doors
    cin >> n >> m;
    int N = 2*n;
    adj.assign(N,{}); radj.assign(N,{});
    for (int d = 0; d < m; d++) {
        int s, k;
        cin >> s >> k;
        vector<int> sw(k);
        for (auto &x : sw) { cin >> x; x--; }
        if (k == 1) {
            int x = sw[0];
            // final = s XOR val(x) = 1  => val(x) = 1 XOR s
            bool needTrue = (1 ^ s) == 1;
            if (needTrue) addClause(x, false, x, false); // force x true
            else addClause(x, true, x, true);            // force x false
        } else {
            int x = sw[0], y = sw[1];
            if (s == 0) {
                // need val(x) XOR val(y) = 1  => (x OR y) AND (not x OR not y)
                addClause(x, false, y, false);
                addClause(x, true, y, true);
            } else {
                // need val(x) == val(y) => (x OR not y) AND (not x OR y)
                addClause(x, false, y, true);
                addClause(x, true, y, false);
            }
        }
    }
    used.assign(N, false);
    for (int i = 0; i < N; i++) if (!used[i]) dfs1(i);
    comp.assign(N, -1);
    int j = 0;
    for (int i = 0; i < N; i++) { int v = order_[N-i-1]; if (comp[v]==-1) dfs2(v, j++); }
    vector<int> val(n);
    bool ok = true;
    for (int i = 0; i < n; i++) {
        if (comp[2*i] == comp[2*i+1]) { ok = false; break; }
        val[i] = (comp[2*i] > comp[2*i+1]) ? 1 : 0;
    }
    if (!ok) { cout << "NO" << endl; return 0; }
    cout << "YES" << endl;
    for (int i = 0; i < n; i++) cout << val[i];
    cout << endl;
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int,int>>> adj(n+1); // (neighbor, edgeId)
    vector<int> deg(n+1, 0);
    for (int e = 0; e < m; e++) {
        int a, b; cin >> a >> b;
        adj[a].push_back({b, e});
        adj[b].push_back({a, e});
        deg[a]++; deg[b]++;
    }
    // feasibility: all vertices with edges have even degree, and they are all
    // in one connected component
    for (int v = 1; v <= n; v++) {
        if (deg[v] % 2 != 0) { cout << "IMPOSSIBLE" << endl; return 0; }
    }
    if (m > 0) {
        vector<bool> vis(n+1, false);
        queue<int> q;
        int startV = -1;
        for (int v = 1; v <= n; v++) if (deg[v] > 0) { startV = v; break; }
        vis[startV] = true; q.push(startV);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto [to, id] : adj[u]) if (!vis[to]) { vis[to] = true; q.push(to); }
        }
        for (int v = 1; v <= n; v++) {
            if (deg[v] > 0 && !vis[v]) { cout << "IMPOSSIBLE" << endl; return 0; }
        }
    }
    // iterative Hierholzer's algorithm starting/ending at node 1
    vector<int> ptr(n+1, 0);
    vector<bool> usedEdge(m, false);
    vector<int> circuit;
    vector<int> st;
    st.push_back(1);
    while (!st.empty()) {
        int v = st.back();
        // advance ptr past used edges
        while (ptr[v] < (int)adj[v].size() && usedEdge[adj[v][ptr[v]].second]) ptr[v]++;
        if (ptr[v] == (int)adj[v].size()) {
            circuit.push_back(v);
            st.pop_back();
        } else {
            auto [to, id] = adj[v][ptr[v]];
            ptr[v]++;
            usedEdge[id] = true;
            st.push_back(to);
        }
    }
    reverse(circuit.begin(), circuit.end());
    if ((int)circuit.size() != m + 1) { cout << "IMPOSSIBLE" << endl; return 0; }
    for (int i = 0; i < (int)circuit.size(); i++) cout << circuit[i] << (i+1<(int)circuit.size()?' ':'\n');
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    int m;
    cin >> m;
    map<string, multiset<string>> adj;
    map<string, int> outDeg, inDeg;
    for (int i = 0; i < m; i++) {
        string a, b;
        cin >> a >> b;
        adj[a].insert(b);
        outDeg[a]++; inDeg[b]++;
    }
    string start = "JFK";
    // iterative Hierholzer's algorithm (directed), always taking the
    // lexicographically smallest unused outgoing edge (multiset keeps sorted order)
    vector<string> stack_;
    vector<string> route;
    stack_.push_back(start);
    while (!stack_.empty()) {
        string v = stack_.back();
        auto it = adj.find(v);
        if (it != adj.end() && !it->second.empty()) {
            auto first = it->second.begin();
            string u = *first;
            it->second.erase(first);
            stack_.push_back(u);
        } else {
            route.push_back(v);
            stack_.pop_back();
        }
    }
    reverse(route.begin(), route.end());
    if ((int)route.size() != m + 1) { cout << "NO VALID ITINERARY" << endl; return 0; }
    for (int i = 0; i < (int)route.size(); i++) cout << route[i] << (i+1<(int)route.size()?' ':'\n');
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    int R, C;
    cin >> R >> C;
    vector<vector<int>> g(R, vector<int>(C));
    for (auto &row : g) for (auto &x : row) cin >> x;
    vector<vector<int>> dist(R, vector<int>(C, INT_MAX));
    deque<pair<int,int>> dq;
    dist[0][0] = (g[0][0] == 1) ? 1 : 0;
    dq.push_back({0,0});
    int dr[4] = {-1,1,0,0}, dc[4] = {0,0,-1,1};
    while (!dq.empty()) {
        auto [r, c] = dq.front(); dq.pop_front();
        for (int k = 0; k < 4; k++) {
            int nr = r+dr[k], nc = c+dc[k];
            if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
            int w = (g[nr][nc] == 1) ? 1 : 0; // cost 1 to move into an obstacle cell, 0 otherwise
            if (dist[r][c] + w < dist[nr][nc]) {
                dist[nr][nc] = dist[r][c] + w;
                if (w == 0) dq.push_front({nr, nc});
                else dq.push_back({nr, nc});
            }
        }
    }
    cout << dist[R-1][C-1] << endl;
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    cin >> n;
    vector<int> a(n+1);
    for (int i = 1; i <= n; i++) cin >> a[i];

    // reversed jump graph: original edge i -> i-a[i] and i -> i+a[i]
    // (when in [1,n]); store the reverse so we can multi-source BFS from a
    // whole parity class and get, for every node, its distance TO that class
    // in the ORIGINAL graph.
    vector<vector<int>> radj(n+1);
    for (int i = 1; i <= n; i++) {
        int lo = i - a[i], hi = i + a[i];
        if (lo >= 1 && lo <= n) radj[lo].push_back(i);
        if (hi >= 1 && hi <= n) radj[hi].push_back(i);
    }

    auto multiSourceDist = [&](int wantParity) {
        vector<int> dist(n+1, -1);
        queue<int> q;
        for (int i = 1; i <= n; i++) {
            if (a[i] % 2 == wantParity) { dist[i] = 0; q.push(i); }
        }
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : radj[u]) {
                if (dist[v] == -1) { dist[v] = dist[u] + 1; q.push(v); }
            }
        }
        return dist;
    };

    vector<int> distToOdd = multiSourceDist(1);
    vector<int> distToEven = multiSourceDist(0);

    for (int i = 1; i <= n; i++) {
        int ans = (a[i] % 2 == 0) ? distToOdd[i] : distToEven[i];
        cout << ans << (i < n ? ' ' : '\n');
    }
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    cin >> n;
    vector<int> nxt(n+1), cost(n+1);
    for (int i = 1; i <= n; i++) cin >> nxt[i];
    for (int i = 1; i <= n; i++) cin >> cost[i];

    vector<int> state(n+1, 0); // 0 = unvisited, 1 = in-progress, 2 = done
    long long answer = 0;

    for (int start = 1; start <= n; start++) {
        if (state[start] != 0) continue;
        vector<int> path;
        unordered_map<int,int> posInPath;
        int v = start;
        while (state[v] == 0) {
            state[v] = 1;
            posInPath[v] = (int)path.size();
            path.push_back(v);
            v = nxt[v];
        }
        if (state[v] == 1) {
            // v lies on the current path -> path[posInPath[v] .. end] is a cycle
            int idx = posInPath[v];
            long long minCost = LLONG_MAX;
            for (int k = idx; k < (int)path.size(); k++) minCost = min(minCost, (long long)cost[path[k]]);
            answer += minCost;
        }
        for (int u : path) state[u] = 2;
    }
    cout << answer << endl;
}

#include <bits/stdc++.h>
using namespace std;

const int LOG = 32; // enough for k up to ~2^32-1

int main(){
    int n;
    cin >> n;
    vector<vector<int>> up(LOG, vector<int>(n+1));
    for (int i = 1; i <= n; i++) cin >> up[0][i];
    for (int j = 1; j < LOG; j++)
        for (int i = 1; i <= n; i++)
            up[j][i] = up[j-1][up[j-1][i]];

    int q;
    cin >> q;
    while (q--) {
        int x; long long k;
        cin >> x >> k;
        for (int j = 0; j < LOG; j++) {
            if (k & (1LL << j)) x = up[j][x];
        }
        cout << x << "\n";
    }
}
